package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Snapshot;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Sets each checked line in order exactly as the rate form would: replacing the grade's rate for the
 *  same from-date, audited RATE_SET and then the figures it moved. */
public class SetImportedRates {
    public void set(@PathVariable("sheetId") String sheetId, @Val ImportedRates imported, @Val Actor actor,
            Rates rates, Rollup rollup, Audit audit, Out<ImportRatesResult> result) {
        RecordRateSet record = new RecordRateSet();
        for (int i = 0; i < imported.rates().size(); i++) {
            Rate rate = imported.rates().get(i);
            Snapshot before = rollup.snapshot(sheetId);
            rates.save(rate);
            record.record(imported.requests().get(i), rate, audit);
            rollup.record(sheetId, before, actor.user());
        }
        result.set(new ImportRatesResult(imported.rates().size()));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the rate is saved, so a refused change writes no audit line. */
public class RecordRateSet {
    public void record(@Val RateRequest request, @Val Rate rate, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + request.user()
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() != null ? " from=" + rate.from() : "")
                + (rate.to() != null ? " to=" + rate.to() : ""));
    }
}
-- The rate for each grade on a sheet: a percent, 0.00 or more, two decimals. A grade with no row
-- has no rate, so its claims' due is n/a. Setting a grade's rate again replaces it.
CREATE TABLE rate (
    sheet_id VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL,
    pct      DECIMAL(7,2) NOT NULL CHECK (pct >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A rate can carry a from-date: a grade may have several rates, and a claim uses the one whose
-- from-date is the latest on or before the claim's date. A rate with no from-date (null) applies
-- from the beginning of time. Setting a rate for a grade and from-date that already exist replaces
-- it; `from_key` is the from-date as compared for that, with null as the earliest date.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
-- A rate can carry a to-date: it applies through that date. A claim dated after the to-date of
-- the rate that would apply to it (the latest from-date on or before its date) has no rate (n/a).
-- Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
